# find connected components of 3s in demo input, bounding boxes and center colors
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and not seen[r][c]:
                stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]!=0:
                                seen[ny][nx]=True; stack.append((ny,nx))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
