                col=next((g[y][x] for y in range(min(rs),max(rs)+1) for x in range(min(cs),max(cs)+1) if g[y][x] not in (0,3)), None)
                out.append((cells,(min(rs),min(cs),max(rs),max(cs)),col))
    return out
